-- 서비스 핵심 테이블 14개와 카테고리 5행 (docs/data-model.md v1 2절, Jira S15P31A102-101)
-- 외래 키가 가리키는 표를 먼저 만든다: 기준표 → 기사 · 수집 → 이슈 · 사건 → 분석 → 회원
-- 기본 키는 bigint 자동 증가(generated by default as identity), 카테고리 · 언론사만 코드 문자열이다(4절)
-- 정해진 값만 받는 칸은 CHECK 로 막는다. 값을 더할 때는 새 마이그레이션에서 이 이름으로 제약을 지우고 다시 건다

-- 1. 기준표 — 카테고리 · 언론사와 원본 값을 맞추는 대응 표

create table category (
    code       text primary key,
    name       text     not null,
    sort_order smallint not null
);

create table category_mapping (
    source        text not null
        constraint category_mapping_source_check check (source in ('SSAFY', 'NEWSDATA')),
    source_value  text not null,
    category_code text references category (code), -- 비어 있으면 대표 카테고리를 고를 때 건너뛴다
    priority      smallint not null,
    primary key (source, source_value)
);

create table press (
    code text primary key,
    name text not null
);

create table press_mapping (
    source       text not null
        constraint press_mapping_source_check check (source in ('SSAFY', 'NEWSDATA')),
    source_value text not null,
    press_code   text not null references press (code),
    primary key (source, source_value)
);

-- 2. 기사 · 수집 실행 기록

create table article (
    id                bigint generated by default as identity primary key,
    source            text        not null
        constraint article_source_check check (source in ('SSAFY_2025H1', 'SSAFY_2024H1', 'SSAFY_2024H2', 'NEWSDATA')),
    url               text        not null unique,
    press_code        text        not null references press (code),
    title             text        not null,
    reporter          text,
    body              text        not null,
    published_at      timestamptz not null,
    category_code     text references category (code),
    source_categories text[]      not null default '{}',
    source_tags       text[],
    source_summary    text,
    released_at       timestamptz, -- 비어 있으면 모든 조회 · 집계에서 없는 기사로 본다 (docs/api.md 1절)
    created_at        timestamptz not null
);

create table ingest_run (
    id            bigint generated by default as identity primary key,
    source        text        not null
        constraint ingest_run_source_check check (source in ('NEWSDATA')),
    started_at    timestamptz not null,
    finished_at   timestamptz,
    fetched_count int,
    next_cursor   text,
    status        text        not null
        constraint ingest_run_status_check check (status in ('RUNNING', 'SUCCEEDED', 'FAILED'))
);

-- 3. 이슈 · 사건 — 이슈 하나에 사건 여러 개, 사건 하나에 기사 여러 개

create table issue (
    id         bigint generated by default as identity primary key,
    title      text        not null,
    summary    text,
    created_at timestamptz not null,
    updated_at timestamptz not null
);

create table issue_category (
    issue_id      bigint not null references issue (id),
    category_code text   not null references category (code),
    primary key (issue_id, category_code)
);

create table event (
    id                bigint generated by default as identity primary key,
    issue_id          bigint references issue (id), -- 비어 있으면 아직 이슈로 묶이지 않은 사건
    title             text        not null,
    label             text        not null,
    summary           text,
    occurred_at       timestamptz not null,
    occurred_at_basis text        not null
        constraint event_occurred_at_basis_check check (occurred_at_basis in ('EXTRACTED', 'FIRST_PUBLISHED')),
    created_at        timestamptz not null,
    updated_at        timestamptz not null
);

-- 기본 키가 article_id 하나라 기사 하나는 사건 하나에만 속한다 (PRD FR-9 가정, data-model.md 5절 1번)
create table article_event (
    article_id bigint primary key references article (id),
    event_id   bigint      not null references event (id),
    linked_at  timestamptz not null
);

-- 4. 분석 작업과 마인드맵 결과

create table analysis_job (
    id            bigint generated by default as identity primary key,
    article_id    bigint      not null references article (id),
    stage         text        not null
        constraint analysis_job_stage_check check (stage in ('EXTRACT', 'EMBED', 'MATCH_EVENT', 'ISSUE')),
    status        text        not null
        constraint analysis_job_status_check check (status in ('QUEUED', 'SUCCEEDED', 'FAILED')),
    requested_by  text        not null
        constraint analysis_job_requested_by_check check (requested_by in ('BATCH')),
    attempt       int         not null
        constraint analysis_job_attempt_check check (attempt >= 1),
    candidates    jsonb, -- MATCH_EVENT · ISSUE 에 보낸 후보. 결과가 후보 밖이면 거절하려고 남긴다
    error_code    text,
    error_message text,
    created_at    timestamptz not null,
    started_at    timestamptz,
    finished_at   timestamptz,
    unique (article_id, stage) -- 기사 하나 · 단계 하나에 한 행. 다시 돌리면 attempt 를 올린다
);

-- 기사 하나에 결과 하나. 다시 분석하면 덮어쓴다
create table article_mindmap (
    article_id     bigint primary key references article (id),
    summary        text,
    content        jsonb       not null, -- 가지 4개와 잎 (docs/api-screen.md 3절)
    occurred_at    timestamptz,
    schema_version text        not null,
    model          text        not null,
    prompt_version text        not null,
    generated_at   timestamptz not null
);

-- 5. 회원과 관심 분야

create table member (
    id            bigint generated by default as identity primary key,
    login_id      text        not null unique,
    password_hash text        not null, -- 해시만 둔다. 원문 비밀번호는 저장하지 않는다
    name          text        not null,
    created_at    timestamptz not null
);

create table member_category (
    member_id     bigint not null references member (id),
    category_code text   not null references category (code),
    primary key (member_id, category_code)
);

